/// Centralized color palette, mapped 1:1 from the original design tokens
/// (`--teal`, `--amber`, `--coral`, `--violet`, `--green`, `--silver`, etc.)
abstract class AppColors {
  AppColors._();

  // ---- Core neutrals ----
  static Color background(bool isLight) => isLight ? const Color(0xFFFFFFFF) : const Color(0xFF121212);
  static Color surface(bool isLight) => isLight ? const Color(0xFFFFFFFF) : const Color(0xFF141B2E);
  static Color ink(bool isLight) => isLight ? const Color(0xFF1C2430) : Colors.white;
  static Color muted(bool isLight) => isLight ? const Color(0xFF707A87) : Colors.white60;
  static Color line(bool isLight) => isLight ? const Color(0x141C2430) : Colors.white12;

  // ---- Brand red ("teal" token) ----
  static const Color tealAccent = Color(0xFFCE1126);
  static Color teal(bool isLight) => isLight ? const Color(0xFFCE1126) : const Color(0xFFE63946);
  static Color tealSoft(bool isLight) => isLight ? const Color(0xFFF9E2E5) : const Color(0xFF2A1A1C);

