  static Color greenGradientMid(bool isLight) => isLight ? greenGradientMidLight : const Color(0xFF4C9A6C);
  static Color greenGradientEnd(bool isLight) => isLight ? greenGradientEndLight : const Color(0xFF66BB6A);

  // ---- Silver ----
