  static Color silverSoft(bool isLight) => isLight ? const Color(0xFFEAEDF1) : const Color(0xFF1A1E26);
  static Color silverInk(bool isLight) => isLight ? const Color(0xFF4C5866) : const Color(0xFFB5BAC2);

