// ---------------------------------------------------------------
/// App-wide Material 3 theme. The Rewards screen mostly uses
/// [AppTextStyles] directly (to match the HTML exactly), but this theme
/// keeps sensible defaults for anything rendered outside that feature.
abstract class AppTheme {
  AppTheme._();

  static ThemeData get light {
    const isLight = true;
    final base = ThemeData(
      useMaterial3: true,
      brightness: Brightness.light,
      scaffoldBackgroundColor: AppColors.background(isLight),
      colorScheme: ColorScheme.fromSeed(
        seedColor: AppColors.tealAccent,
        brightness: Brightness.light,
        primary: AppColors.tealAccent,
        surface: AppColors.surface(isLight),
      ),
      fontFamily: GoogleFonts.playfairDisplay().fontFamily,
    );

    return base.copyWith(
      textTheme: GoogleFonts.playfairDisplayTextTheme(base.textTheme),
      splashFactory: InkRipple.splashFactory,
      dividerColor: AppColors.line(isLight),
      appBarTheme: AppBarTheme(
        backgroundColor: AppColors.background(isLight),
        elevation: 0,
        surfaceTintColor: Colors.transparent,
      ),
    );
  }

  static ThemeData get dark {
    const isLight = false;
    final base = ThemeData(
      useMaterial3: true,
      brightness: Brightness.dark,
      scaffoldBackgroundColor: AppColors.background(isLight),
      colorScheme: ColorScheme.fromSeed(
        seedColor: AppColors.tealAccent,
        brightness: Brightness.dark,
        primary: AppColors.teal(isLight),
        surface: AppColors.surface(isLight),
      ),
      fontFamily: GoogleFonts.playfairDisplay().fontFamily,
    );

    return base.copyWith(
      textTheme: GoogleFonts.playfairDisplayTextTheme(base.textTheme),
      splashFactory: InkRipple.splashFactory,
      dividerColor: AppColors.line(isLight),
      appBarTheme: AppBarTheme(
        backgroundColor: AppColors.background(isLight),
        elevation: 0,
        surfaceTintColor: Colors.transparent,
      ),
    );
  }
}

