@immutable
class GreenLevel {
  final String name;
  final int minPoints;
  final IconData icon;

  const GreenLevel({
    required this.name,
    required this.minPoints,
    required this.icon,
  });
}

@immutable
class GreenAchievement {
  final String label;
  final int count;
  final String source;

  const GreenAchievement({
    required this.label,
    required this.count,
    required this.source,
  });
}

/// Result of resolving a green-points total against [GreenLevel] tiers.
@immutable
class GreenLevelInfo {
  final GreenLevel current;
  final GreenLevel? next;
  final double progress; // 0..1

  const GreenLevelInfo({
    required this.current,
    required this.next,
    required this.progress,
  });

  static GreenLevelInfo resolve(int points, List<GreenLevel> levels) {
    var current = levels.first;
    for (final level in levels) {
      if (points >= level.minPoints) current = level;
    }
    final idx = levels.indexOf(current);
    final next = idx + 1 < levels.length ? levels[idx + 1] : null;
    final progress = next == null
        ? 1.0
        : ((points - current.minPoints) /
                (next.minPoints - current.minPoints))
            .clamp(0.0, 1.0);
    return GreenLevelInfo(current: current, next: next, progress: progress);
  }
}

