@immutable
class LeaderboardEntry {
  final String name;
  final int points;
  final bool isMe;

  const LeaderboardEntry({
    required this.name,
    required this.points,
    this.isMe = false,
  });

  String get initials => name
      .split(' ')
      .where((s) => s.isNotEmpty)
      .map((s) => s[0])
      .join();
