// ---------------------------------------------------------------
/// A circular (or rounded-square) colored badge holding an icon or emoji.
/// Reused for avatars, mission icons, history icons, voucher icons, etc.
/// (`.avatar`, `.reco-icon`, `.streak-icon`, `.hicon`, `.voucher-icon`,
/// `.mrow-icon`, `.rd-icon`, `.achv-emoji`, `.board-icon`, `.ga-icon` ...)
class IconBadge extends StatelessWidget {
  final IconData? icon;
  final String? emoji;
  final Color background;
  final Color? iconColor;
  final double size;
  final double iconSize;
  final double borderRadius;

  const IconBadge({
    super.key,
    this.icon,
    this.emoji,
    required this.background,
    this.iconColor,
    this.size = 36,
    this.iconSize = 17,
    double? borderRadius,
  }) : borderRadius = borderRadius ?? 999;

  @override
  Widget build(BuildContext context) {
    return Container(
      width: size,
      height: size,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: background,
        borderRadius: BorderRadius.circular(borderRadius),
      ),
      child: emoji != null
          ? Text(emoji!, style: TextStyle(fontSize: iconSize))
          : Icon(icon, size: iconSize, color: iconColor),
    );
  }
}

