/// `.section-row` — a section title with an optional trailing "See all" link.
class SectionHeader extends StatelessWidget {
  final String title;
  final String? actionLabel;
  final VoidCallback? onAction;
  final EdgeInsetsGeometry? padding;

  const SectionHeader({
    super.key,
    required this.title,
    this.actionLabel,
    this.onAction,
    this.padding,
  });

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness != Brightness.dark;
    return Padding(
      padding: padding ??
          const EdgeInsetsDirectional.only(
            start: AppSpacing.screenHorizontal,
            end: AppSpacing.screenHorizontal,
            top: AppSpacing.xl,
          ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(title, style: AppTextStyles.sectionTitle(isLight)),
          if (actionLabel != null)
            GestureDetector(
              onTap: onAction,
              behavior: HitTestBehavior.opaque,
              child: Text(actionLabel!, style: AppTextStyles.linkButton(isLight)),
            ),
        ],
      ),
    );
  }
}

