// from: widgets/app_bottom_sheet_scaffold.dart
// ---------------------------------------------------------------
/// Shared shell for every bottom sheet in the Rewards feature:
/// grabber handle + title/subtitle header + close button, matching
/// `.sheet`, `.grabber`, `.sheet-head`, `.close-btn` in the original CSS.
class AppBottomSheetScaffold extends StatelessWidget {
  final String title;
  final String? subtitle;
  final Widget child;
  final bool showHeader;

  const AppBottomSheetScaffold({
    super.key,
    required this.title,
    this.subtitle,
    required this.child,
    this.showHeader = true,
  });

  static Future<T?> show<T>({
    required BuildContext context,
    required WidgetBuilder builder,
  }) {
    return showModalBottomSheet<T>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: AppColors.overlayScrim,
      builder: (context) => builder(context),
    );
  }

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness != Brightness.dark;
    final maxHeight = MediaQuery.of(context).size.height * 0.85;

    return SafeArea(
      top: false,
      child: ConstrainedBox(
        constraints: BoxConstraints(maxHeight: maxHeight),
        child: Container(
          decoration: BoxDecoration(
            color: AppColors.background(isLight),
            borderRadius: AppRadius.sheetTop,
          ),
          padding: const EdgeInsetsDirectional.fromSTEB(
            AppSpacing.screenHorizontal,
            AppSpacing.lg,
            AppSpacing.screenHorizontal,
            AppSpacing.xxl + AppSpacing.xs,
          ),
          child: SingleChildScrollView(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Center(
                  child: Container(
                    width: 36,
                    height: 6,
                    margin: const EdgeInsets.only(bottom: 10),
                    decoration: BoxDecoration(
                      color: AppColors.line(isLight),
                      borderRadius: AppRadius.rPill,
                    ),
                  ),
                ),
                if (showHeader)
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(title, style: AppTextStyles.sheetH1(isLight)),
                            if (subtitle != null) ...[
                              const SizedBox(height: 4),
                              Text(subtitle!, style: AppTextStyles.sheetH2(isLight)),
                            ],
                          ],
                        ),
                      ),
                      _CloseButton(onTap: () => Navigator.of(context).pop()),
                    ],
                  ),
                child,
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _CloseButton extends StatelessWidget {
  final VoidCallback onTap;
  const _CloseButton({required this.onTap});

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness != Brightness.dark;
    final surfaceColor = AppColors.surface(isLight);
    final bgColor = AppColors.background(isLight);
    return Material(
      color: surfaceColor == bgColor
          ? (isLight ? const Color(0xFFF5F4F0) : const Color(0xFF1A1F2E))
          : surfaceColor,
      shape: const CircleBorder(),
      child: InkWell(
        onTap: onTap,
        customBorder: const CircleBorder(),
        child: SizedBox(
          width: 28,
          height: 28,
          child: Icon(Icons.close, size: 14, color: AppColors.ink(isLight)),
        ),
      ),
    );
  }
}

