// ---------------------------------------------------------------
// from: features/rewards/presentation/widgets/points_ring.dart
// ---------------------------------------------------------------
class PointsRing extends StatelessWidget {
  final int points;
  final int goal;
  final int pointsToNextTier;
  final String tierGoalLabel;

  const PointsRing({
    super.key,
    required this.points,
    required this.goal,
    required this.pointsToNextTier,
    required this.tierGoalLabel,
  });

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness != Brightness.dark;
    final progress = (points / goal).clamp(0.0, 1.0);

    return Center(
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: AppSpacing.md),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            SizedBox(
              width: 200,
              height: 200,
              child: Stack(
                alignment: Alignment.center,
                children: [
                  SizedBox(
                    width: 200,
                    height: 200,
                    child: CircularProgressIndicator(
                      value: progress,
                      strokeWidth: 14,
                      backgroundColor: AppColors.ringTrack(isLight),
                      valueColor: AlwaysStoppedAnimation<Color>(
                        AppColors.teal(isLight),
                      ),
                      strokeCap: StrokeCap.round,
                    ),
                  ),
                  Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        '$points',
                        style: AppTextStyles.ringPoints(isLight),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        AppScope.of(context).t('rewards_points'),
                        style: AppTextStyles.ringLabel(isLight),
                      ),
                    ],
                  ),
                ],
              ),
            ),
            const SizedBox(height: 12),
            Text(
              AppScope.of(context).t('rewards_pointsToTier', {
                'points': '$pointsToNextTier',
                'tier': tierGoalLabel,
              }),
              style: AppTextStyles.ringSub(isLight),
              textAlign: TextAlign.center,
            ),
          ],
        ),
      ),
    );
  }
}

