    this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness != Brightness.dark;
    return Stack(
      clipBehavior: Clip.none,
      children: [
        Material(
          color: (isLight ? Colors.white : const Color(0xFF2A2F3E)).withOpacity(0.67),
          shape: const CircleBorder(),
          child: InkWell(
            customBorder: const CircleBorder(),
            onTap: onTap,
            child: SizedBox(
              width: 36,
              height: 36,
              child: Icon(icon, size: iconSize, color: AppColors.ink(isLight)),
            ),
          ),
        ),
        if (showDot)
          Positioned(
            top: 6,
            right: 6,
            child: Container(
              width: 8,
              height: 8,
              decoration: const BoxDecoration(
                color: AppColors.coral,
                shape: BoxShape.circle,
