    final subLabel = info.next != null
        ? '$greenPoints of ${info.next!.minPoints} points to ${info.next!.name}'
        : 'Highest level reached';

    return AppBottomSheetScaffold(
      title: AppScope.of(context).t('rewards_greenLevelSheetTitle'),
