                child: Icon(info.current.icon,
                    size: 24, color: AppColors.greenInk(isLight)),
              ),
              const SizedBox(width: AppSpacing.mdl),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(info.current.name,
