class RewardDetailSheet extends StatelessWidget {
  final Reward reward;
  final int points;
  final bool redeemed;
  final VoidCallback onRedeem;
  final VoidCallback onDone;

  const RewardDetailSheet({
    super.key,
    required this.reward,
    required this.points,
    required this.redeemed,
    required this.onRedeem,
    required this.onDone,
  });

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness != Brightness.dark;
    if (redeemed) {
      return AppBottomSheetScaffold(
        title: '',
        showHeader: false,
        child: _RedeemedState(reward: reward, onDone: onDone),
      );
    }

    final canAfford = points >= reward.points && !reward.locked;
    final surfaceColor = AppColors.surface(isLight);
    final bgColor = AppColors.background(isLight);
    final surfaceVariant = isLight ? const Color(0xFFF5F4F0) : const Color(0xFF2A2A33);

    return AppBottomSheetScaffold(
      title: '',
      showHeader: false,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: 56,
                height: 56,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color: reward.softColor,
                  borderRadius: BorderRadius.circular(AppRadius.lg),
                ),
                child: Icon(reward.icon, size: 24, color: reward.color),
              ),
              const SizedBox(width: AppSpacing.mdl),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(reward.title, style: AppTextStyles.rdTitle(isLight)),
                    const SizedBox(height: 4),
                    Text(reward.description, style: AppTextStyles.rdDesc(isLight)),
                  ],
                ),
              ),
              Material(
                color: surfaceVariant,
                shape: const CircleBorder(),
                child: InkWell(
                  customBorder: const CircleBorder(),
                  onTap: () => Navigator.of(context).pop(),
                  child: SizedBox(
                    width: 28,
                    height: 28,
                    child: Icon(Icons.close, size: 14, color: AppColors.ink(isLight)),
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),
          Wrap(
            spacing: 14,
            runSpacing: 6,
            children: [
              _MetaChip(
                icon: Icons.location_on_outlined,
                label: AppScope.of(context).t('rewards_availableLocations'),
              ),
              _MetaChip(
                icon: Icons.access_time,
                label: AppScope.of(context).t('rewards_valid30Days'),
              ),
            ],
          ),
          const SizedBox(height: 20),
          Container(
            padding: const EdgeInsets.all(AppSpacing.mdl),
            decoration: BoxDecoration(
              color: bgColor.value == surfaceColor.value
                  ? surfaceVariant
                  : surfaceColor,
              borderRadius: BorderRadius.circular(AppRadius.lg),
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(AppScope.of(context).t('rewards_costLabel'), style: AppTextStyles.rdCostLabel(isLight)),
                Text(AppScope.of(context).t('rewards_pointsSuffix', {'points': '${reward.points}'}),
                    style: AppTextStyles.rdCostValue(isLight)),
              ],
            ),
          ),
          const SizedBox(height: 16),
          if (reward.locked)
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color: AppColors.violetSoft(isLight),
                borderRadius: BorderRadius.circular(AppRadius.lg),
              ),
              child: Text(
                AppScope.of(context).t('rewards_reachToUnlock', {'points': '${reward.points}'}),
                textAlign: TextAlign.center,
                style: AppTextStyles.rdLocked(isLight),
              ),
            )
          else
            SizedBox(
              width: double.infinity,
              child: Material(
                color: canAfford ? AppColors.teal(isLight) : AppColors.disabledBg(isLight),
                borderRadius: BorderRadius.circular(AppRadius.lg),
                child: InkWell(
                  borderRadius: BorderRadius.circular(AppRadius.lg),
                  onTap: canAfford ? onRedeem : null,
                  child: Padding(
                    padding: const EdgeInsets.all(14),
                    child: Center(
                      child: Text(
                        canAfford ? 'Redeem now' : 'Not enough points',
                        style: AppTextStyles.rdButton(isLight).copyWith(
                          color:
                              canAfford ? Colors.white : AppColors.muted(isLight),
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }
}

