class RewardsPage extends StatefulWidget {
  const RewardsPage({super.key});

  @override
  State<RewardsPage> createState() => _RewardsPageState();
}

class _RewardsPageState extends State<RewardsPage> {
  int _points = RewardsData.startingPoints;
  int _greenPoints = RewardsData.startingGreenPoints;
  late List<HistoryEntry> _history = [];

  void _openMissionsSheet() {
    final isLight = Theme.of(context).brightness != Brightness.dark;
    MissionsSheet.show(context, RewardsData.missions(isLight, AppScope.of(context).t));
  }

  void _openLeaderboardSheet() =>
      LeaderboardSheet.show(context, RewardsData.leaderboard(AppScope.of(context).t));

  void _openHistorySheet() => HistorySheet.show(context, _history);

  Future<void> _openGreenSheet() async {
    final isLight = Theme.of(context).brightness != Brightness.dark;
    bool converted = false;

    await showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: AppColors.overlayScrim,
      builder: (sheetContext) {
        return StatefulBuilder(
          builder: (sheetContext, setSheetState) {
            final info = GreenLevelInfo.resolve(
              _greenPoints,
              RewardsData.greenLevels(AppScope.of(context).t),
            );
            return GreenLevelSheet(
              info: info,
              greenPoints: _greenPoints,
              achievements: RewardsData.greenAchievements(AppScope.of(context).t),
              infoFact: RewardsData.greenInfoFact(AppScope.of(context).t),
              converted: converted,
              onConvert: () {
                if (_greenPoints <= 0) return;
                setState(() {
                  _points += _greenPoints;
                  _history = [
                    HistoryEntry(
                      label: AppScope.of(context).t('rewards_convertedGreenPoints'),
                      points: _greenPoints,
                      when: AppScope.of(context).t('rewards_todayLabel'),
                      icon: Icons.eco_outlined,
                    ),
                    ..._history,
                  ];
                  _greenPoints = 0;
                });
                setSheetState(() => converted = true);
              },
              onDone: () => Navigator.of(sheetContext).pop(),
            );
          },
        );
      },
    );
  }

  Future<void> _openRewardSheet(String rewardId) async {
    final isLight = Theme.of(context).brightness != Brightness.dark;
    final reward =
        RewardsData.rewards(isLight, AppScope.of(context).t).firstWhere((r) => r.id == rewardId);
    bool redeemed = false;

    await showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: AppColors.overlayScrim,
      builder: (sheetContext) {
        return StatefulBuilder(
          builder: (sheetContext, setSheetState) {
            return RewardDetailSheet(
              reward: reward,
              points: _points,
              redeemed: redeemed,
              onRedeem: () {
                setState(() {
                  _points -= reward.points;
                });
                setSheetState(() => redeemed = true);
              },
              onDone: () => Navigator.of(sheetContext).pop(),
            );
          },
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness != Brightness.dark;
    final t = AppScope.of(context).t;
    final missions = RewardsData.missions(isLight, t);
    final rewards = RewardsData.rewards(isLight, t);
    final vouchers = RewardsData.vouchers(isLight, t);
    if (_history.isEmpty) {
      _history = List.of(RewardsData.history(t));
    }
    final activeMissions =
        missions.where((m) => !m.done).toList();
    final greenInfo =
        GreenLevelInfo.resolve(_greenPoints, RewardsData.greenLevels(t));

    return Scaffold(
      backgroundColor: AppColors.background(isLight),
      body: SafeArea(
        child: SingleChildScrollView(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              RewardsTopBar(
                userInitial: RewardsData.userInitial,
                greeting: RewardsData.greeting(t),
                userName: RewardsData.userName,
                onHistoryTap: _openHistorySheet,
              ),
              Padding(
                padding: const EdgeInsets.symmetric(
                    horizontal: AppSpacing.screenHorizontal),
                child: Text(AppScope.of(context).t('rewards_pageTitle'), style: AppTextStyles.title(isLight)),
              ),

              Center(
                child: PointsRing(
                  points: _points,
                  goal: RewardsData.ringGoal,
                  pointsToNextTier: RewardsData.pointsToNextTier,
                  tierGoalLabel: RewardsData.tierGoalLabel(t),
                ),
              ),

              StatsRow(trips: RewardsData.trips, tier: RewardsData.tier),
              LevelProgressCard(level: RewardsData.levelData(t)),
              RecommendationCard(
                subtitle: RewardsData.recommendationCopy(t),
                onPressed: () =>
                    _openRewardSheet(RewardsData.recommendedRewardId),
              ),
              GreenHeroCard(
                info: greenInfo,
                greenPoints: _greenPoints,
                onTap: _openGreenSheet,
              ),
              StreakCard(
                days: RewardsData.streakDays,
                barsFilled: RewardsData.streakBarsFilled,
                barsTotal: RewardsData.streakBarsTotal,
              ),
              SectionHeader(
                title: t('rewards_earnMorePoints'),
                actionLabel: t('profile_seeAll'),
                onAction: _openMissionsSheet,
              ),
              SizedBox(
                height: 96,
                child: ListView.separated(
                  scrollDirection: Axis.horizontal,
                  padding: const EdgeInsets.symmetric(
                    horizontal: AppSpacing.screenHorizontal,
                    vertical: 8,
                  ),
                  itemCount: activeMissions.length,
                  separatorBuilder: (_, __) =>
                      const SizedBox(width: AppSpacing.smd),
                  itemBuilder: (context, index) =>
                      MissionMiniCard(mission: activeMissions[index]),
                ),
              ),
              SectionHeader(
                title: t('rewards_recentActivity'),
                actionLabel: t('profile_seeAll'),
                onAction: _openHistorySheet,
              ),
              Padding(
                padding: const EdgeInsetsDirectional.fromSTEB(
                  AppSpacing.screenHorizontal,
                  8,
                  AppSpacing.screenHorizontal,
                  0,
                ),
                child: Column(
                  children: [
                    for (int i = 0;
                        i < RewardsData.recentActivity(t).length;
                        i++) ...[
                      HistoryRow(
                        entry: RewardsData.recentActivity(t)[i],
                        showWhen: false,
                      ),
                      if (i != RewardsData.recentActivity(t).length - 1)
                        const SizedBox(height: 8),
                    ],
                  ],
                ),
              ),
              LeaderboardTeaserCard(
                rankLabel: RewardsData.boardRankLabel(t),
                subLabel: RewardsData.boardSubLabel(t),
                onTap: _openLeaderboardSheet,
              ),
              AchievementCard(
                emoji: RewardsData.achievementEmoji,
                title: RewardsData.achievementTitle(t),
                subtitle: RewardsData.achievementSub(t),
              ),
              SectionHeader(title: t('rewards_yourVouchers')),

              SizedBox(
                height: 210,
                child: ListView.separated(
                  scrollDirection: Axis.horizontal,
                  padding: const EdgeInsets.symmetric(
                    horizontal: AppSpacing.screenHorizontal,
                    vertical: 8,
                  ),
                  itemCount: vouchers.length,
                  separatorBuilder: (_, __) =>
                      const SizedBox(width: AppSpacing.smd),
                  itemBuilder: (context, index) {
                    final voucher = vouchers[index];
                    return VoucherCard(
                      voucher: voucher,
                      onRedeem: voucher.rewardId != null
                          ? () => _openRewardSheet(voucher.rewardId!)
                          : null,
                    );
                  },
                ),
              ),

              SectionHeader(title: t('rewards_redeemYourPoints')),
              Padding(
                padding: const EdgeInsetsDirectional.fromSTEB(
                  AppSpacing.screenHorizontal,
                  8,
                  AppSpacing.screenHorizontal,
                  16,
                ),
                child: Column(
                  children: [
                    for (int i = 0; i < rewards.length; i++) ...[
                      RewardListCard(
                        reward: rewards[i],
                        onTap: () =>
                            _openRewardSheet(rewards[i].id),
                      ),
                      if (i != rewards.length - 1)
                        const SizedBox(height: 10),
                    ],
                  ],
                ),
              ),
              PointsExpiryCard(detail: RewardsData.expireLabel),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------------------------------------------------------
// from: main.dart (app + entry point)
// ---------------------------------------------------------------
void main() {
  runApp(const AxnApp());
}

class AxnApp extends StatelessWidget {
  const AxnApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'AXN',
      debugShowCheckedModeBanner: false,
      theme: AppTheme.light,
      darkTheme: AppTheme.dark,
      themeMode: ThemeMode.system,
      home: const RewardsPage(),
    );
  }
}
